def backfill_engagement_money(apps, schema_editor):
    """Fill the six new money columns before their constraints exist.

    Added as `default=0`, which would violate `requirements_engagement_stages_reconcile_to_total`
    on the very next statement for every engagement created in Wave C2. Three deliberate choices:

    * `staged_total_paise` takes `total_paise`, not the sum of the engagement's stages. The agreed
      total is what both parties signed; a pre-C3 A3 engagement whose stage rows do not add up to
      it is a defect this wave closes going forward (`proposals._assert_a3_shape` now refuses that
      quote), and recording the discrepancy as an `amendment_delta_paise` would file a bug under
      the word "amendment" in the audit trail.
    * `funded_paise` takes the stage amount wherever `funding_state` is already `FUNDED`, because
      `complete_stage_funding` has always refused a short payment — a funded stage was funded at
      face value.
    * `funded_total_paise` is **clamped** to the engagement's total. It is the one number that
      could otherwise contradict the exposure constraint on a legacy row whose stages overshoot,
      and clamping states the smaller, safer figure rather than failing the migration on data that
      predates the rule.
    """
    Engagement = apps.get_model("requirements", "Engagement")
    EngagementStage = apps.get_model("requirements", "EngagementStage")

    EngagementStage.objects.filter(funding_state="FUNDED").update(
        funded_paise=models.F("amount_paise")
    )
    for engagement in Engagement.objects.all().iterator():
        funded = (
            EngagementStage.objects.filter(
                engagement_id=engagement.id, funding_state="FUNDED"
            ).aggregate(total=models.Sum("amount_paise"))["total"]
            or 0
        )
        Engagement.objects.filter(pk=engagement.pk).update(
            staged_total_paise=engagement.total_paise,
            amendment_delta_paise=0,
            funded_total_paise=min(funded, engagement.total_paise),
        )


